  const handleUploadImageFile = async (file, target = "post") => {
    if (!file) return;
    setNavaratriUploading(true);
    setNavaratriMessage("");

    const formData = new FormData();
    formData.append("photo", file);

    const token = typeof window !== "undefined" ? localStorage.getItem("admin_token") : null;
    try {
      const res = await fetch(`${API_BASE_URL}/navaratri/upload`, {
        method: "POST",
        headers: {
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
        },
        body: formData,
      });

      const data = await res.json();
      if (!res.ok || !data.success) {
        throw new Error(data.error || "Upload failed");
      }

      const rawUrl = data.imageUrl || data.fileUrl || data.photo_url || data.url || "";
      const uploadedUrl = (rawUrl.startsWith("http") || rawUrl.startsWith("data:") || rawUrl.startsWith("blob:"))
        ? rawUrl
        : `${API_BASE_URL}${rawUrl.startsWith("/") ? rawUrl : `/${rawUrl}`}`;
      if (target === "post") {
        setNewNavaratriPost((prev) => ({ ...prev, image_url: uploadedUrl }));
        setPostImagePreview(uploadedUrl);
      } else if (target === "banner") {
        setNavaratriSettings((prev) => ({ ...prev, banner_image: uploadedUrl }));
        setBannerImagePreview(uploadedUrl);
      } else if (target === "sponsor") {
        setNewSponsor((prev) => ({ ...prev, logo_url: uploadedUrl }));
        setSponsorLogoPreview(uploadedUrl);
      } else if (target === "ad_banner") {
        setNavaratriSettings((prev) => ({ ...prev, ad_banner_url: uploadedUrl }));
      } else if (target === "audio") {
        setNavaratriSettings((prev) => ({ ...prev, bg_audio_url: uploadedUrl }));
      }
      setNavaratriMessage("✅ File uploaded successfully!");
    } catch (err) {
      console.error("Upload error 👉", err);
      setNavaratriMessage("❌ Upload failed: " + err.message);
    } finally {
      setNavaratriUploading(false);
    }
  };

