  const handleUploadAssocFile = async (e, target) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setAssocUploading(true);
    setAssocMessage("");
    try {
      const formData = new FormData();
      formData.append("image", file);
      const token = localStorage.getItem("admin_token");
      const res = await fetch(`${API_BASE_URL}/association-posts/upload`, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
        },
        body: formData,
      });
      const data = await res.json();
      if (!res.ok || !data.success) {
        throw new Error(data.error || "Upload failed");
      }
      const rawUrl = data.fileUrl || data.imageUrl || data.photo_url || data.url || "";
      const uploadedUrl = (rawUrl.startsWith("http") || rawUrl.startsWith("data:") || rawUrl.startsWith("blob:"))
        ? rawUrl
        : `${API_BASE_URL}${rawUrl.startsWith("/") ? rawUrl : `/${rawUrl}`}`;
      if (target === "new_member") {
        setNewAssocMember((prev) => ({ ...prev, photo_url: uploadedUrl }));
        setAssocMemberPhotoPreview(uploadedUrl);
      } else if (target === "edit_member") {
        setEditingAssocMember((prev) => ({ ...prev, photo_url: uploadedUrl }));
        setAssocMemberPhotoPreview(uploadedUrl);
      } else if (target === "new_post") {
        setNewAssocPost((prev) => ({ ...prev, image_url: uploadedUrl }));
        setAssocPostPhotoPreview(uploadedUrl);
      } else if (target === "edit_post") {
        setEditingAssocPost((prev) => ({ ...prev, image_url: uploadedUrl }));
        setAssocPostPhotoPreview(uploadedUrl);
      }
      setAssocMessage("✅ Photo uploaded successfully!");
    } catch (err) {
      console.error("Upload error 👉", err);
      setAssocMessage("❌ Upload failed: " + err.message);
    } finally {
      setAssocUploading(false);
    }
  };

