  const exportVolunteersCSV = () => {
    if (!volunteers || volunteers.length === 0) return;
    const headers = ["ID", "Name", "Phone", "Email", "City", "Occupation", "Blood Group", "Interests", "Availability", "Status", "Notes", "Applied Date"];
    const rows = volunteers.map((v) => [
      v.id,
      `"${(v.name || "").replace(/"/g, '""')}"`,
      `"${(v.phone || "").replace(/"/g, '""')}"`,
      `"${(v.email || "").replace(/"/g, '""')}"`,
      `"${(v.city || "").replace(/"/g, '""')}"`,
      `"${(v.occupation || "").replace(/"/g, '""')}"`,
      `"${(v.blood_group || "").replace(/"/g, '""')}"`,
      `"${(v.areas_of_interest || "").replace(/"/g, '""')}"`,
      `"${(v.availability || "").replace(/"/g, '""')}"`,
      `"${(v.status || "PENDING").replace(/"/g, '""')}"`,
      `"${(v.notes || "").replace(/"/g, '""')}"`,
      `"${new Date(v.created_at).toLocaleDateString("en-IN")}"`,
    ]);
    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(","), ...rows.map((r) => r.join(","))].join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `Hindu_Swaraj_Volunteers_${new Date().toISOString().split("T")[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

