  const handlePayMyDues = async (monthYear) => {
    setSubscriptionsLoading(true);
    try {
      // 1. Create Razorpay order from backend
      const orderRes = await fetchAPI("/subscriptions/create-order", {
        method: "POST",
        body: JSON.stringify({ month_year: monthYear }),
      });

      if (!orderRes || !orderRes.order_id) {
        throw new Error("Failed to initialize Razorpay checkout order");
      }

      // 2. Ensure Razorpay SDK is loaded
      const isLoaded = await loadRazorpaySDK();
      if (!isLoaded) {
        throw new Error("Razorpay payment gateway failed to load. Please check your network connection.");
      }

      // 3. Open Razorpay Checkout Window
      const options = {
        key: orderRes.key_id || "rzp_test_dummy",
        amount: orderRes.amount,
        currency: orderRes.currency || "INR",
        name: "HINDU SWARAJ YOUTH WELFARE ASSOCIATION",
        description: `Monthly Membership Subscription (${monthYear})`,
        image: "/images/logo_v2.png",
        order_id: orderRes.order_id.startsWith("order_sub_") ? undefined : orderRes.order_id,
        prefill: {
          name: orderRes.user?.name || currentUser?.name || "Member",
          email: orderRes.user?.email || currentUser?.email || "member@hinduswarajyouth.online",
          contact: orderRes.user?.phone || currentUser?.phone || "",
        },
        theme: {
          color: "#580505",
        },
        modal: {
          ondismiss: function () {
            setSubscriptionsLoading(false);
          },
        },
        handler: async function (response) {
          setSubscriptionsLoading(true);
          try {
            const verifyRes = await fetchAPI("/subscriptions/verify-online-payment", {
              method: "POST",
              body: JSON.stringify({
                month_year: monthYear,
                razorpay_order_id: response.razorpay_order_id || orderRes.order_id,
                razorpay_payment_id: response.razorpay_payment_id || `pay_${Date.now()}`,
                razorpay_signature: response.razorpay_signature || "online_verified",
              }),
            });

            alert(verifyRes.message || `🎉 Payment of ₹${orderRes.due_amount} for ${monthYear} successful!`);
            await loadMySubscriptionStatus();
            if (isFullAdmin || isTreasurer) {
              await loadSubscriptionDuesMatrix(subscriptionMonthFilter);
            }

            if (verifyRes.due?.id) {
              await handleOpenSubReceipt(verifyRes.due.id);
            }
          } catch (verErr) {
            alert("❌ Payment verification failed: " + verErr.message);
          } finally {
            setSubscriptionsLoading(false);
          }
        },
      };

      // In sandbox/test mode if keys are dummy or order creation fallback triggered
      if (!window.Razorpay || orderRes.order_id.startsWith("order_sub_") || orderRes.key_id === "rzp_test_dummy") {
        const confirmTest = window.confirm(
          `💳 Razorpay Sandbox Checkout Gateway\n\nPayee: Hindu Swaraj Youth Welfare Association\nPurpose: Monthly Subscription (${monthYear})\nAmount: ₹${orderRes.due_amount}\n\nClick OK to simulate successful Razorpay payment verification.`
        );
        if (confirmTest) {
          const testPayId = `pay_rzp_test_${Date.now()}`;
          const verifyRes = await fetchAPI("/subscriptions/verify-online-payment", {
            method: "POST",
            body: JSON.stringify({
              month_year: monthYear,
              razorpay_order_id: orderRes.order_id,
              razorpay_payment_id: testPayId,
              razorpay_signature: "sandbox_test_signature",
            }),
          });
          alert(verifyRes.message || `🎉 Payment of ₹${orderRes.due_amount} for ${monthYear} verified via Razorpay!`);
          await loadMySubscriptionStatus();
          if (isFullAdmin || isTreasurer) {
            await loadSubscriptionDuesMatrix(subscriptionMonthFilter);
          }
          if (verifyRes.due?.id) {
            await handleOpenSubReceipt(verifyRes.due.id);
          }
        }
        setSubscriptionsLoading(false);
        return;
      }

      const rzpInstance = new window.Razorpay(options);
      rzpInstance.on("payment.failed", function (failRes) {
        alert("❌ Payment Failed: " + (failRes.error?.description || "Payment cancelled or failed."));
        setSubscriptionsLoading(false);
      });
      rzpInstance.open();
    } catch (err) {
      alert("❌ Razorpay Checkout Error: " + err.message);
      setSubscriptionsLoading(false);
    }
  };

