  const handleOpenEditProfile = () => {
    const src = idCardProfile || currentUser || {};
    setProfileForm({
      name: src.name || "",
      phone: src.phone || "",
      personal_email: src.personal_email || src.email || "",
      blood_group: src.blood_group || "B+",
      address: src.address || "Jagtial, Telangana",
      photo_url: src.photo_url || "/images/leader-president.png",
    });
    setProfileMessage(null);
    setShowEditProfileModal(true);
  };

  const handleUploadProfilePhoto = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setProfilePhotoUploading(true);
    try {
      const formData = new FormData();
      formData.append("image", file);
      const token = localStorage.getItem("admin_token");
      const res = await fetch(`${API_BASE_URL}/association-posts/upload`, {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
        body: formData,
      });
      const data = await res.json();
      if (!res.ok || !data.success) {
        throw new Error(data.error || "Failed to upload photo");
      }
      const rawUrl = data.fileUrl || data.imageUrl || data.photo_url || data.url || "";
      const uploadedUrl = (rawUrl.startsWith("http") || rawUrl.startsWith("data:") || rawUrl.startsWith("blob:"))
        ? rawUrl
        : `${API_BASE_URL}${rawUrl.startsWith("/") ? rawUrl : `/${rawUrl}`}`;
      setProfileForm((prev) => ({ ...prev, photo_url: uploadedUrl }));
    } catch (err) {
      alert("❌ Photo upload error: " + err.message);
    } finally {
      setProfilePhotoUploading(false);
    }
  };

  const handleSaveProfile = async (e) => {
    e.preventDefault();
    setProfileLoading(true);
    setProfileMessage(null);
    try {
      const isEditingOther = idCardProfile && idCardProfile.id && currentUser && String(idCardProfile.id) !== String(currentUser.id);

      let res;
      if (isEditingOther) {
        res = await fetchAPI(`/members/${idCardProfile.id}`, {
          method: "PUT",
          body: JSON.stringify({
            name: profileForm.name,
            phone: profileForm.phone,
            personal_email: profileForm.personal_email,
            blood_group: profileForm.blood_group,
            address: profileForm.address,
            photo_url: profileForm.photo_url,
            role: idCardProfile.role,
            active: idCardProfile.active !== false,
          }),
        });
      } else {
        res = await fetchAPI("/auth/profile", {
          method: "PUT",
          body: JSON.stringify({
            name: profileForm.name,
            phone: profileForm.phone,
            personal_email: profileForm.personal_email,
            blood_group: profileForm.blood_group,
            address: profileForm.address,
            photo_url: profileForm.photo_url,
          }),
        });
      }

      const updatedUser = {
        ...(idCardProfile || currentUser || {}),
        name: profileForm.name,
        phone: profileForm.phone,
        personal_email: profileForm.personal_email,
        blood_group: profileForm.blood_group,
        address: profileForm.address,
        photo_url: profileForm.photo_url,
      };

      if (!isEditingOther) {
        setCurrentUser(updatedUser);
      }
      setIdCardProfile(updatedUser);
      setProfileMessage({ type: "success", text: res.message || "Profile & ID Card updated successfully! ✅" });
      if (typeof loadMembers === "function") {
        await loadMembers();
      }
      setTimeout(() => setShowEditProfileModal(false), 1200);
    } catch (err) {
      setProfileMessage({ type: "error", text: err.message || "Failed to update profile." });
    } finally {
      setProfileLoading(false);
    }
  };

