      console.warn(
        "Failed to store fund in database, saving locally:",
        err.message,
      );
      const updated = [...funds, fundObj];
      setFunds(updated);
      localStorage.setItem("admin_funds", JSON.stringify(updated));
      setNewFund({ name: "", type: "MONTHLY", amount: "" });

