          title: newMeeting.title,
          description: newMeeting.desc,
          meeting_type: newMeeting.meeting_type || "GBM",
          meeting_date: newMeeting.dateTime,
          location: newMeeting.location || "Association Chamber (Head Office)",
          presided_by: newMeeting.presided_by || "President",
          convener: newMeeting.convener || "General Secretary",
