  const handleOpenMeetingChamber = async (meeting) => {
    setSelectedMeeting(meeting);
    setMeetingChamberTab("overview");
    setMeetingMinutesInput(meeting.minutes_text || "");
    await handleRefreshChamberData(meeting.id);
  };

  const handleRefreshChamberData = async (meetingId) => {
    setMeetingLoading(true);
    try {
      const [attRes, resRes] = await Promise.allSettled([
        fetchAPI(`/meetings/attendance/${meetingId}`),
        fetchAPI(`/meetings/resolution/${meetingId}`),
      ]);
      if (attRes.status === "fulfilled") {
        setMeetingAttendance(attRes.value);
      }
      if (resRes.status === "fulfilled") {
        setMeetingResolutions(Array.isArray(resRes.value) ? resRes.value : []);
      }
    } catch (err) {
      console.warn("Chamber refresh error:", err.message);
    } finally {
      setMeetingLoading(false);
    }
  };

  const handleSelfCheckIn = async (meetingId) => {
    try {
      const res = await fetchAPI(`/meetings/check-in/${meetingId}`, {
        method: "POST",
      });
      alert(res.message || "Attendance recorded: PRESENT! ✅");
      await handleRefreshChamberData(meetingId);
    } catch (err) {
      alert("Check-in error: " + err.message);
    }
  };

  const handleUpdateMemberAttendance = async (meetingId, userId, newStatus) => {
    try {
      await fetchAPI(`/meetings/attendance/${meetingId}/update`, {
        method: "POST",
        body: JSON.stringify({ user_id: userId, status: newStatus }),
      });
      await handleRefreshChamberData(meetingId);
    } catch (err) {
      alert("Failed to update attendance: " + err.message);
    }
  };

  const handleProposeResolution = async (e) => {
    e.preventDefault();
    if (!selectedMeeting || !newResolution.title || !newResolution.content) {
      alert("Please provide Resolution Title and Description.");
      return;
    }
    setMeetingLoading(true);
    try {
      const res = await fetchAPI(`/meetings/resolution/${selectedMeeting.id}`, {
        method: "POST",
        body: JSON.stringify({
          title: newResolution.title,
          content: newResolution.content,
          voting_rule: newResolution.voting_rule || "TWO_THIRDS",
          quorum_required: Number(newResolution.quorum_required) || 67,
          vote_deadline: newResolution.vote_deadline || null,
        }),
      });
      alert(res.message || "Resolution tabled for 2/3 voting! 🗳️");
      setProposingResolution(false);
      setNewResolution({
        title: "",
        content: "",
        voting_rule: "TWO_THIRDS",
        quorum_required: 67,
        vote_deadline: "",
      });
      await handleRefreshChamberData(selectedMeeting.id);
    } catch (err) {
      alert("Failed to create resolution: " + err.message);
    } finally {
      setMeetingLoading(false);
    }
  };

  const handleCastVote = async (resolutionId, voteChoice) => {
    if (!window.confirm(`Confirm your official vote: "${voteChoice}" on this resolution?`)) {
      return;
    }
    setMeetingLoading(true);
    try {
      const res = await fetchAPI(`/meetings/vote/${resolutionId}`, {
        method: "POST",
        body: JSON.stringify({ vote: voteChoice }),
      });
      alert(res.message || `Vote recorded: ${voteChoice}!`);
      if (selectedMeeting) {
        await handleRefreshChamberData(selectedMeeting.id);
      }
    } catch (err) {
      alert("Failed to cast vote: " + err.message);
    } finally {
      setMeetingLoading(false);
    }
  };

  const handleViewVoters = async (resolution) => {
    try {
      const voters = await fetchAPI(`/meetings/votes/${resolution.id}`);
      setSelectedResolutionVoters({
        resolution,
        voters: Array.isArray(voters) ? voters : [],
      });
    } catch (err) {
      alert("Failed to load voters list: " + err.message);
    }
  };

  const handleLockResolution = async (resolutionId, forceStatus) => {
    if (!window.confirm(`Are you sure you want to finalize this resolution as "${forceStatus}"?`)) {
      return;
    }
    setMeetingLoading(true);
    try {
      const res = await fetchAPI(`/meetings/resolution-lock/${resolutionId}`, {
        method: "PUT",
        body: JSON.stringify({ force_status: forceStatus }),
      });
      alert(res.message || `Resolution status locked to ${forceStatus}.`);
      if (selectedMeeting) {
        await handleRefreshChamberData(selectedMeeting.id);
      }
    } catch (err) {
      alert("Failed to lock resolution: " + err.message);
    } finally {
      setMeetingLoading(false);
    }
  };

  const handleSaveMinutes = async (meetingId) => {
    if (!meetingMinutesInput.trim()) {
      alert("Please write the Minutes of Meeting (MoM) summary.");
      return;
    }
    setMeetingLoading(true);
    try {
      const res = await fetchAPI(`/meetings/minutes/${meetingId}`, {
        method: "POST",
        body: JSON.stringify({
          minutes_text: meetingMinutesInput,
          status: "CONCLUDED",
        }),
      });
      alert(res.message || "Minutes of Meeting saved & meeting status marked CONCLUDED! 📜");
      if (selectedMeeting) {
        setSelectedMeeting({ ...selectedMeeting, minutes_text: meetingMinutesInput, status: "CONCLUDED" });
      }
      await loadMeetingsData();
    } catch (err) {
      alert("Failed to save minutes: " + err.message);
    } finally {
      setMeetingLoading(false);
    }
  };

  const handleOpenMoMPrint = async (meetingId) => {
    setMomPrinting(true);
    try {
      const data = await fetchAPI(`/meetings/mom-print/${meetingId}`);
      setMomData(data);
    } catch (err) {
      alert("Failed to prepare MoM print: " + err.message);
    } finally {
      setMomPrinting(false);
    }
  };

  const handleDeleteMeeting = async (id) => {
    if (!window.confirm("Are you sure you want to delete this meeting? All associated attendance and resolutions will be removed.")) {
      return;
    }
    try {
      await fetchAPI(`/meetings/${id}`, { method: "DELETE" });
      alert("Meeting deleted successfully.");
      if (selectedMeeting?.id === id) {
        setSelectedMeeting(null);
      }
      await loadMeetingsData();
    } catch (err) {
      alert("Failed to delete meeting: " + err.message);
    }
  };

  const handleDeleteFund = async (id) => {
    if (
      !confirm(
        "Are you sure you want to delete this fund? This will also remove related ledger entries and contributions.",
      )
    ) {
      return;
    }
    try {
      await fetchAPI(`/funds/${id}`, {
        method: "DELETE",
      });
      loadAllData();
    } catch (err) {
      console.warn(
        "Failed to delete fund from database, deleting locally:",
        err.message,
      );
      const updated = funds.filter((f) => f.id !== id);
      setFunds(updated);
      localStorage.setItem("admin_funds", JSON.stringify(updated));
    }
  };

  const handleUploadExpenseBill = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setExpenseBillUploading(true);
    try {
      const formData = new FormData();
      formData.append("bill", file);
      const token = localStorage.getItem("admin_token");
      const res = await fetch(`${API_BASE_URL}/expenses/upload-bill`, {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
        body: formData,
      });
      const data = await res.json();
      if (!res.ok || !data.success) {
        throw new Error(data.error || "Bill upload failed");
      }
      const rawUrl = data.fileUrl || data.imageUrl || data.photo_url || data.url || "";
      const uploadedUrl = (rawUrl.startsWith("http") || rawUrl.startsWith("data:") || rawUrl.startsWith("blob:"))
        ? rawUrl
        : `${API_BASE_URL}${rawUrl.startsWith("/") ? rawUrl : `/${rawUrl}`}`;
      setNewExpense((prev) => ({ ...prev, bill_url: uploadedUrl }));
      setExpenseBillPreview(uploadedUrl);
    } catch (err) {
      alert("Failed to upload bill: " + err.message);
    } finally {
      setExpenseBillUploading(false);
    }
  };

  const handleAddExpense = async (e) => {
    e.preventDefault();
    if (
      !newExpense.title ||
      !newExpense.amount ||
      !newExpense.expense_date ||
      !newExpense.fund_id
    ) {
      alert("Please fill in all required fields (*).");
      return;
    }

    try {
      await fetchAPI("/expenses", {
        method: "POST",
        body: JSON.stringify({
          title: newExpense.title,
          category: newExpense.category || "GENERAL",
          description: newExpense.desc || "",
          amount: Number(newExpense.amount),
          expense_date: newExpense.expense_date,
          fund_id: Number(newExpense.fund_id),
          bill_url: newExpense.bill_url || null,
        }),
      });
      loadAllData();
    } catch (err) {
      console.warn(
        "Failed to store expense in database, saving locally:",
        err.message,
      );
      const expenseObj = {
        id: Date.now(),
        title: newExpense.title,
        category: newExpense.category || "GENERAL",
        desc: newExpense.desc,
        amount: Number(newExpense.amount),
        date: newExpense.expense_date,
        status: "PENDING",
        fund_id: newExpense.fund_id,
        bill_url: newExpense.bill_url,
      };

      const updated = [expenseObj, ...expenses];
      setExpenses(updated);
      localStorage.setItem("admin_expenses", JSON.stringify(updated));
    }

    // Reset Form
    setNewExpense({
      title: "",
      category: "",
      desc: "",
      amount: "",
      expense_date: new Date().toISOString().split("T")[0],
      status: "PENDING",
      fund_id: "",
      bill_url: "",
    });
    setExpenseBillPreview("");
    setShowExpenseModal(false);
  };

  const handleApproveExpense = async (id) => {
    if (
      !confirm(
        "Are you sure you want to approve this expense? This will debit the corresponding fund balance.",
      )
    ) {
      return;
    }
    try {
      await fetchAPI(`/expenses/${id}/approve`, {
        method: "PUT",
      });
      loadAllData();
    } catch (err) {
      console.warn(
        "Failed to approve expense in database, falling back locally:",
        err.message,
      );
      const updated = expenses.map((e) => {
        if (e.id === id) {
          return { ...e, status: "APPROVED" };
        }
        return e;
      });
      setExpenses(updated);
      localStorage.setItem("admin_expenses", JSON.stringify(updated));
    }
  };

  const handleCancelExpense = (id) => {
    openCancelExpenseModal(id);
  };

  const handleOpenViewExpense = (item) => {
    setViewingExpense(item);
  };

  const handleOpenEditExpense = (item) => {
    setEditingExpense({
      id: item.id,
      title: item.title || "",
      category: item.category || "",
      fund_id: item.fund_id || "",
      amount: item.amount || "",
      expense_date: item.date || new Date().toISOString().split("T")[0],
      desc: item.desc || "",
      bill_url: item.bill_url || "",
      status: item.status || "PENDING",
    });
    setEditExpenseBillPreview(item.bill_url || "");
    if (viewingExpense) setViewingExpense(null);
  };

  const handleUploadEditExpenseBill = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setEditExpenseUploading(true);
    try {
      const formData = new FormData();
      formData.append("bill", file);
      const token = localStorage.getItem("admin_token");
      const res = await fetch(`${API_BASE_URL}/expenses/upload-bill`, {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
        body: formData,
      });
      const data = await res.json();
      if (!res.ok || !data.success) {
        throw new Error(data.error || "Bill upload failed");
      }
      const rawUrl = data.fileUrl || data.imageUrl || data.photo_url || data.url || "";
      const uploadedUrl = (rawUrl.startsWith("http") || rawUrl.startsWith("data:") || rawUrl.startsWith("blob:"))
        ? rawUrl
        : `${API_BASE_URL}${rawUrl.startsWith("/") ? rawUrl : `/${rawUrl}`}`;
      setEditingExpense((prev) => ({ ...prev, bill_url: uploadedUrl }));
      setEditExpenseBillPreview(uploadedUrl);
    } catch (err) {
      alert("Failed to upload bill: " + err.message);
    } finally {
      setEditExpenseUploading(false);
    }
  };

  const handleUpdateExpense = async (e) => {
    e.preventDefault();
    if (
      !editingExpense.title ||
      !editingExpense.amount ||
      !editingExpense.expense_date ||
      !editingExpense.fund_id
    ) {
      alert("Please fill in all required fields (*).");
      return;
    }

    try {
      await fetchAPI(`/expenses/${editingExpense.id}`, {
        method: "PUT",
        body: JSON.stringify({
          title: editingExpense.title,
          category: editingExpense.category || "GENERAL",
          description: editingExpense.desc || "",
          amount: Number(editingExpense.amount),
          expense_date: editingExpense.expense_date,
          fund_id: Number(editingExpense.fund_id),
          bill_url: editingExpense.bill_url || null,
        }),
      });
      loadAllData();
      setEditingExpense(null);
      setEditExpenseBillPreview("");
      alert("✅ Expense updated and corrected successfully!");
    } catch (err) {
      alert("Failed to update expense: " + err.message);
    }
  };

  const handleDeleteExpense = async (id) => {
    if (!confirm("Are you sure you want to permanently delete this pending expense?")) {
      return;
    }
    try {
      await fetchAPI(`/expenses/${id}`, {
        method: "DELETE",
      });
      loadAllData();
      if (viewingExpense && viewingExpense.id === id) setViewingExpense(null);
      alert("✅ Expense deleted successfully.");
    } catch (err) {
      alert("Failed to delete expense: " + err.message);
    }
  };

  const handlePassExpense = async (expenseId) => {
    const notes = prompt(
      "Enter verification note for President approval:",
      "Verified & Passed by General Secretary"
    );
    if (notes === null) return; // User pressed Cancel

    try {
      await fetchAPI(`/expenses/${expenseId}/pass`, {
        method: "PUT",
        body: JSON.stringify({ notes }),
      });
      loadAllData();
      if (viewingExpense && viewingExpense.id === expenseId) {
        setViewingExpense((prev) => ({
          ...prev,
          status: "PASSED_BY_GS",
          passed_by_name: userName || "General Secretary",
          passed_at: new Date().toISOString(),
          passed_notes: notes,
        }));
      }
      alert("✅ Expense bill verified and passed to President for final disbursement approval!");
    } catch (err) {
      alert("Failed to pass expense: " + err.message);
    }
  };

  const handleSaveSignatures = async (e) => {
    if (e) e.preventDefault();
    setSavingSignatures(true);
    try {
      await fetchAPI("/association-settings/signatures", {
        method: "PUT",
        body: JSON.stringify(signatures),
      });
      alert("✅ Digital signatures and authority names saved successfully!");
      setShowSignaturesModal(false);
    } catch (err) {
      alert("Failed to save signatures: " + err.message);
    } finally {
      setSavingSignatures(false);
    }
  };

  const handleUploadSignature = async (roleKey, file) => {
    if (!file) return;
    try {
      setUploadingSignRole(roleKey);
      const formData = new FormData();
      formData.append("signature", file);
      formData.append("role", roleKey);
      const token = localStorage.getItem("admin_token");
      const res = await fetch(`${API_BASE_URL}/association-settings/signatures/upload`, {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
        body: formData,
      });
      const data = await res.json();
      if (!res.ok || !data.success) {
        throw new Error(data.error || "Upload failed");
      }
      const rawUrl = data.fileUrl || data.imageUrl || data.photo_url || data.url || "";
      const uploadedUrl = (rawUrl.startsWith("http") || rawUrl.startsWith("data:") || rawUrl.startsWith("blob:"))
        ? rawUrl
        : `${API_BASE_URL}${rawUrl.startsWith("/") ? rawUrl : `/${rawUrl}`}`;

      const updated = {
        ...signatures,
        [roleKey]: uploadedUrl,
      };
      setSignatures(updated);

      // Persist in backend
      await fetchAPI("/association-settings/signatures", {
        method: "PUT",
        body: JSON.stringify(updated),
      });

      alert(`✅ Official signature for ${roleKey.replace(/_/g, " ").toUpperCase()} updated successfully!`);
    } catch (err) {
      alert("Failed to upload signature: " + err.message);
    } finally {
      setUploadingSignRole("");
    }
  };

