                  border: `1px solid ${myLoanEligibility.is_eligible ? "#22c55e" : "#475569"}`,
                  borderRadius: "12px",
                  padding: "16px 22px",
                  marginBottom: "24px",
                  color: "#ffffff",
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  flexWrap: "wrap",
                  gap: "14px",
                  boxShadow: "0 4px 12px rgba(0,0,0,0.15)",
